    <h1>Memeory Match</h1>
    <div class="stats">
        <span>Moves: <b id="move-count">0</b></span>
        <span>Time: <b id="time-count">00:00</b></span>
    </div>

    <div class="game-container" id="game-board">
        <!-- Cards generated by JS -->
    </div>

    <button onclick="startGame()">Restart Game</button>

    <script>
        const gameBoard = document.getElementById('game-board');
        const moveDisplay = document.getElementById('move-count');
        const timeDisplay = document.getElementById('time-count');

        // The items to match (Emojis)
        const items = ['🍕', '🚀', '🐱', '🌵', '🎸', '🍦', '🎈', '⚽'];

        let cardsArray = [];
        let hasFlippedCard = false;
        let lockBoard = false;
        let firstCard, secondCard;
        let moves = 0;
        let matches = 0;
        let timer;
        let seconds = 0;

        function startGame() {
            // Reset State
            moves = 0;
            matches = 0;
            seconds = 0;
            moveDisplay.innerText = moves;
            timeDisplay.innerText = "00:00";
            gameBoard.innerHTML = '';

            // Stop existing timer if any
            clearInterval(timer);

            // Show initial cards
            showCards();
        }

        function showCards() {
            // Duplicate items to make pairs
            cardsArray = [...items, ...items];

            // Shuffle
            cardsArray.sort(() => 0.5 - Math.random());

            // Create HTML elements
            cardsArray.forEach(item => {
                const card = document.createElement('div');
                card.classList.add('card');
                card.dataset.item = item;

                const frontFace = document.createElement('div');
                frontFace.classList.add('card-front');
                frontFace.innerText = '?'; // Or a generic icon

                const backFace = document.createElement('div');
                backFace.classList.add('card-back');
                backFace.innerText = item;

                card.appendChild(frontFace);
                card.appendChild(backFace);

                card.addEventListener('click', flipCard);
                gameBoard.appendChild(card);
            });

            // Start Timer
            startTimer();
        }

        function flipCard() {
            if (lockBoard) return;
            if (this === firstCard) return;

            this.classList.add('flip');

            if (!hasFlippedCard) {
                // First click
                hasFlippedCard = true;
                firstCard = this;
                return;
            }

            // Second click
            secondCard = this;
            incrementMoves();
            checkForMatch();
        }

        function checkForMatch() {
            let isMatch = firstCard.dataset.item === secondCard.dataset.item;

            isMatch ? disableCards() : unflipCards();
        }

        function disableCards() {
            firstCard.removeEventListener('click', flipCard);
            secondCard.removeEventListener('click', flipCard);

            // Visual indicator for match
            firstCard.classList.add('matched');
            secondCard.classList.add('matched');

            matches++;
            resetBoard();

            if (matches === items.length) {
                clearInterval(timer);
                setTimeout(() => alert(`You won in ${seconds} seconds!`), 500);
            }
        }

        function unflipCards() {
            lockBoard = true;

            setTimeout(() => {
                firstCard.classList.remove('flip');
                secondCard.classList.remove('flip');
                resetBoard();
            }, 1000);
        }

        function resetBoard() {
            [hasFlippedCard, lockBoard] = [false, false];
            [firstCard, secondCard] = [null, null];
        }

        function incrementMoves() {
            moves++;
            moveDisplay.innerText = moves;
        }

        function startTimer() {
            timer = setInterval(() => {
                seconds++;
                const mins = Math.floor(seconds / 60);
                const secs = seconds % 6
